'use strict';
const $=id=>document.getElementById(id), P=window.Petrol;
const colours={short:'#21705d',medium:'#af771a',long:'#a54135',unknown:'#727d82'};
const STORE='bali-petrol-checks-v1', ORIGIN='bali-petrol-origin-v1';
let dataset,stations=[],selected=null,map=null,markers=[],originMarker=null,origin=null,choosing=false,mapReady=false,toastTimer;
const e=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const readStorage=key=>{try{return JSON.parse(localStorage.getItem(key)||'null')}catch{return null}};
let checks=readStorage(STORE)||{};
const storedOrigin=readStorage(ORIGIN);
if(Array.isArray(storedOrigin)&&storedOrigin.length===2&&storedOrigin.every(Number.isFinite)&&Math.abs(storedOrigin[0])<=180&&Math.abs(storedOrigin[1])<=90)origin=storedOrigin;
function notify(message){$('toast').textContent=message;$('toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').hidden=true,3600)}
function writeStorage(key,value){try{localStorage.setItem(key,JSON.stringify(value));return true}catch{return false}}
function dateLabel(date){return new Intl.DateTimeFormat('en-GB',{day:'2-digit',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit',hour12:false,timeZone:'Asia/Makassar'}).format(new Date(date)).replace(',',' ·')+' WITA'}
function ageLabel(date){if(!date)return 'Not checked';const minutes=Math.max(0,Math.floor((Date.now()-Date.parse(date))/60000));return minutes<1?'Just now':minutes<60?`${minutes} min ago`:minutes<1440?`${Math.floor(minutes/60)} hr ago`:`${Math.floor(minutes/1440)} days ago`}
function snapshotLabel(){return isOld(dataset.checkedAt)?'Older observations · not live':'Saved observations · not live'}
function isOld(date){return !date||Date.now()-Date.parse(date)>3600000}
function googleStation(s){return `https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(s.name+' Bali')}${s.placeId?'&query_place_id='+encodeURIComponent(s.placeId):''}`}
function trafficUrl(s){return `https://www.google.com/maps/@${s.coordinates[1]},${s.coordinates[0]},17z/data=!5m1!1e1`}
function directionsUrl(s){return `https://www.google.com/maps/dir/?api=1&destination=${s.coordinates[1]},${s.coordinates[0]}${s.placeId?'&destination_place_id='+encodeURIComponent(s.placeId):''}${origin?'&origin='+origin[1]+','+origin[0]:''}&travelmode=driving`}
function activeStations(){return P.ordered(stations.filter(s=>(s.name+' '+s.area+' '+s.address).toLowerCase().includes($('search').value.trim().toLowerCase())),$('sort').value,origin,$('fuel').value)}
function stockLabel(value){return ({available:'reported available',out:'reported out',unknown:'unconfirmed'})[value||'unknown']}
function rankLabel(s){const a=P.availability(s,$('fuel').value);if(a==='out')return 'Reported out of selected fuel';if(!s.length)return 'Traffic not checked';if(s.id===P.ordered(stations,'congestion',origin,$('fuel').value)[0]?.id)return 'Shortest recorded red stretch';return 'Recorded traffic observation'}
function applyChecks(){stations=dataset.stations.map((s,index)=>{const c=checks[s.id];return {...s,number:index+1,...(P.validCheck(c)&&(!s.checkedAt||Date.parse(c.checkedAt)>=Date.parse(s.checkedAt))?{length:c.length,checkedAt:c.checkedAt,stock:c.stock,personal:true,note:'Your saved check. Recheck conditions before setting off.'}:{stock:{pertalite:'unknown',pertamax:'unknown',...s.stock}})}})}
function renderList(){const list=activeStations();$('count').textContent=`${list.length} of ${stations.length}`;
 $('list-caption').textContent=$('sort').value==='distance'?(origin?'Straight-line distance from your start':'Set your start above · showing red-road order'):$('sort').value==='name'?'Alphabetical order':'Ranked by observed red-road length';
 $('stations').innerHTML=list.length?list.map(s=>{const colour=colours[P.severity(s)],av=P.availability(s,$('fuel').value);return `<li><button class="station-row" data-station="${s.id}" aria-pressed="${s.id===selected}" style="--pin:${colour}"><span class="station-number">${s.number}</span><span><span class="row-heading"><strong>${e(s.shortName)}</strong>${origin?`<span class="distance">${P.distance(origin,s.coordinates).toFixed(1)} km</span>`:''}</span><span class="row-sub">${e(s.area)}${s.personal?' · Your check':''}</span><span class="row-bottom"><span>${P.formatLength(s.length)}${s.length?' red':''}</span>${s.length?`<span class="length-bar" aria-hidden="true"><i style="width:${Math.min(100,P.mean(s)/1300*100)}%"></i></span>`:''}</span>${s.checkedAt?`<span class="row-age">${e(ageLabel(s.checkedAt))}${isOld(s.checkedAt)?' · recheck traffic':''}</span>`:''}${av!=='unknown'?`<span class="row-stock">Fuel ${stockLabel(av)}${isOld(s.checkedAt)?' · older check':''}</span>`:''}</span></button></li>`}).join(''):'<li class="empty">No stations match this search.<br><button class="text-button" id="clear-search">Clear search</button></li>';
 document.querySelectorAll('[data-station]').forEach(b=>b.addEventListener('click',()=>selectStation(b.dataset.station,true,true)));
 $('clear-search')?.addEventListener('click',()=>{$('search').value='';renderList()});
 markers.forEach(({id,marker,element})=>{const s=stations.find(x=>x.id===id);element.style.display=list.some(x=>x.id===id)?'':'none';element.style.setProperty('--pin',colours[P.severity(s)]);element.setAttribute('aria-pressed',String(id===selected));element.setAttribute('aria-label',`${s.name}, ${P.formatLength(s.length)}${s.length?' of recorded red road':''}`)});
}
function renderDetail(){const s=stations.find(x=>x.id===selected);if(!s){$('detail').hidden=true;return}$('detail').hidden=false;$('detail').style.setProperty('--pin',colours[P.severity(s)]);
 const nowWita=new Date(Date.now()+8*3600000).toISOString().slice(0,16);
 $('detail').innerHTML=`<div class="detail-header"><span class="detail-kicker">${e(rankLabel(s))}</span><button id="close-detail" aria-label="Close station details">×</button></div><h2>${e(s.shortName)}</h2><p class="address">${e(s.address)}</p><div class="measure"><span>Observed red-road length</span><strong>${P.formatLength(s.length)}</strong></div><p class="checked">${s.checkedAt?`${s.personal?'Your check':'Google Maps observation'} · ${dateLabel(s.checkedAt)}${isOld(s.checkedAt)?'<br><strong>Older observation — check live traffic.</strong>':''}`:'No congestion measurement recorded.'}</p><p class="observation">${e(s.note)}</p><div class="stock-line"><span class="${s.stock.pertalite}">Pertalite ${stockLabel(s.stock.pertalite)}</span><span class="${s.stock.pertamax}">Pertamax ${stockLabel(s.stock.pertamax)}</span></div><div class="detail-actions"><a href="${trafficUrl(s)}" target="_blank" rel="noopener noreferrer">Live traffic ↗</a><a href="${directionsUrl(s)}" target="_blank" rel="noopener noreferrer">Directions ↗</a></div>
 <details id="wait-details"><summary>Try a waiting-time estimate</summary><p>A scenario for a motorbike queue. Assumes the whole measured stretch leads to this station’s pumps.</p><div class="calculator-grid"><label>Red stretch, from (m)<input id="wait-min" type="number" min="0" max="10000" value="${s.length?.[0]??''}" placeholder="e.g. 100"></label><label>To (m)<input id="wait-max" type="number" min="0" max="10000" value="${s.length?.[1]??''}" placeholder="e.g. 200"></label><label>Space per bike (m)<input id="spacing" type="number" min="1" max="10" step="0.5" value="2.5"></label><label>Bikes side by side<input id="rows" type="number" min="1" max="6" step="1" value="1"></label><label>Active pump attendants<input id="pumps" type="number" min="1" max="20" step="1" value="2"></label><label>Seconds per bike<input id="seconds" type="number" min="10" max="600" step="5" value="45"></label></div><output id="wait-result" class="wait-output" aria-live="polite"></output><p>Assumption-based, not a measured wait. Add time for any queue inside the station. If pumps stop, this estimate no longer applies.</p></details>
 <details id="check-details"><summary>Add your check</summary><p>Save what you see for this browser. Leave length blank if you only checked fuel availability.</p><form id="check-form"><div class="check-grid"><label>Red stretch, from (m)<input id="check-min" type="number" min="0" max="10000" step="10" placeholder="Not measured"></label><label>To (m)<input id="check-max" type="number" min="0" max="10000" step="10" placeholder="Not measured"></label><label>Pertalite<select id="stock-pertalite"><option value="unknown">Not checked</option><option value="available">Available</option><option value="out">Out of stock</option></select></label><label>Pertamax<select id="stock-pertamax"><option value="unknown">Not checked</option><option value="available">Available</option><option value="out">Out of stock</option></select></label></div><label>Observed at (Bali time)<input id="check-time" type="datetime-local" value="${nowWita}" required></label><p id="check-status" class="form-status" role="status"></p><button type="submit" class="save-check">Save my check</button></form></details>
 <div class="detail-bottom"><a href="${googleStation(s)}" target="_blank" rel="noopener" class="text-button">Station listing ↗</a><button class="text-button" id="copy-link">Copy station link</button>${s.personal?'<button class="text-button" id="remove-check">Remove my check</button>':''}</div>`;
 $('close-detail').addEventListener('click',()=>{selected=null;history.replaceState(null,'',location.pathname+location.search);renderDetail();renderList()});
 const estimate=()=>{const ids=['wait-min','wait-max','spacing','rows','pumps','seconds'],values=ids.map(id=>Number($(id).value));if(ids.some(id=>!$(id).value||!$(id).checkValidity())||values[0]>values[1]){$('wait-result').textContent='Enter a valid length range and pump assumptions.';return}const range=P.waitRange(values.slice(0,2),...values.slice(2));$('wait-result').textContent=`Scenario: ${range[0]}–${range[1]} minutes`};
 ['wait-min','wait-max','spacing','rows','pumps','seconds'].forEach(id=>$(id).addEventListener('input',estimate));estimate();
 $('check-form').addEventListener('submit',event=>{event.preventDefault();const min=$('check-min').value,max=$('check-max').value;const stock={pertalite:$('stock-pertalite').value,pertamax:$('stock-pertamax').value};const c={length:min===''&&max===''?null:[Number(min),Number(max)],stock,checkedAt:$('check-time').value+':00+08:00'};if((min===''&&max!=='')||(min!==''&&max==='')||!P.validCheck(c)||Date.parse(c.checkedAt)>Date.now()+600000){$('check-status').textContent='Use a valid range and a time no more than 10 minutes in the future.';return}if(!c.length&&stock.pertalite==='unknown'&&stock.pertamax==='unknown'){$('check-status').textContent='Add a road length or fuel availability before saving.';return}checks[s.id]=c;const saved=writeStorage(STORE,checks);applyChecks();renderList();renderDetail();notify(saved?'Your check is saved on this device.':'Check applied for this visit; browser storage is unavailable.')});
 $('remove-check')?.addEventListener('click',()=>{delete checks[s.id];writeStorage(STORE,checks);applyChecks();renderList();renderDetail();notify('Your check was removed. Original observation restored.')});
 $('copy-link').addEventListener('click',async()=>{try{await navigator.clipboard.writeText(location.origin+location.pathname+'#'+s.id);notify('Station link copied.')}catch{notify('Use the address bar to copy this station’s link.')}});
}
function selectStation(id,fly=true,scroll=false){selected=id;history.replaceState(null,'',location.pathname+location.search+'#'+id);renderList();renderDetail();const s=stations.find(x=>x.id===id);if(map&&fly){map.flyTo({center:s.coordinates,zoom:14.5,offset:matchMedia('(min-width:761px)').matches?[120,0]:[0,0],duration:matchMedia('(prefers-reduced-motion:reduce)').matches?0:600})}if(scroll&&matchMedia('(max-width:760px)').matches){$('detail').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'auto':'smooth',block:'start'});$('detail').focus({preventScroll:true})}}
function updateOrigin(){if(origin){$('origin-status').textContent=`Distances from your selected point · straight-line km`;$('clear-origin').hidden=false;if(map){originMarker?.remove();const el=document.createElement('div');el.className='origin-pin';el.setAttribute('aria-label','Your starting point');originMarker=new maplibregl.Marker({element:el}).setLngLat(origin).addTo(map)}}else{$('origin-status').textContent='Set a starting point to compare distances.';$('clear-origin').hidden=true;originMarker?.remove();originMarker=null}renderList();renderDetail()}
function setChoosing(on){choosing=on;$('choose-point').setAttribute('aria-pressed',String(on));$('map-prompt').hidden=!on;if(map)map.getCanvas().style.cursor=on?'crosshair':''}
function fitAll(){if(!map)return;const list=activeStations();if(!list.length)return;const bounds=new maplibregl.LngLatBounds();list.forEach(s=>bounds.extend(s.coordinates));if(origin)bounds.extend(origin);const desktop=matchMedia('(min-width:761px)').matches;const narrow=$('map').clientWidth<700;map.fitBounds(bounds,{padding:{top:120,bottom:75,left:desktop&&!narrow?350:65,right:65},maxZoom:14,duration:matchMedia('(prefers-reduced-motion:reduce)').matches?0:500})}
function initMap(){if(!window.maplibregl){$('map-error').hidden=false;return}try{map=new maplibregl.Map({container:'map',style:'https://tiles.openfreemap.org/styles/positron',center:[115.201,-8.787],zoom:13,minZoom:8,maxZoom:18,attributionControl:false,cooperativeGestures:matchMedia('(pointer:coarse)').matches});map.addControl(new maplibregl.NavigationControl({showCompass:false}),'top-right');map.addControl(new maplibregl.AttributionControl({compact:false}),'bottom-right');map.addControl(new maplibregl.ScaleControl({maxWidth:90,unit:'metric'}),'bottom-right');markers=stations.map(s=>{const element=document.createElement('button');element.className='map-pin';element.textContent=s.number;element.style.setProperty('--pin',colours[P.severity(s)]);element.setAttribute('aria-label',s.name);element.addEventListener('click',event=>{event.stopPropagation();if(!choosing)selectStation(s.id,true,true)});return {id:s.id,element,marker:new maplibregl.Marker({element}).setLngLat(s.coordinates).addTo(map)}});map.on('load',()=>{mapReady=true;$('map-error').hidden=true;fitAll()});map.on('click',event=>{if(!choosing)return;origin=[event.lngLat.lng,event.lngLat.lat];writeStorage(ORIGIN,origin);setChoosing(false);updateOrigin();notify('Starting point selected.')});setTimeout(()=>{if(!mapReady)$('map-error').hidden=false},12000);updateOrigin();renderList()}catch{$('map-error').hidden=false}}
async function loadData(initial=false){$('reload').disabled=true;try{const response=await fetch('observations.json?t='+Date.now(),{cache:'no-store'});if(!response.ok)throw Error('Unavailable');const incoming=await response.json();if(!Array.isArray(incoming.stations)||!incoming.stations.length)throw Error('Invalid data');dataset=incoming;applyChecks();$('snapshot-title').textContent=snapshotLabel();$('snapshot-time').textContent='Latest shared check: '+dateLabel(dataset.checkedAt);if(initial){selected=stations.some(s=>s.id===location.hash.slice(1))?location.hash.slice(1):'nusa-dua';renderList();renderDetail();initMap()}else{renderList();renderDetail();notify('Saved data reloaded. Latest observation: '+dateLabel(dataset.checkedAt)+'. Traffic was not remeasured.')}}catch{if(initial){$('stations').innerHTML='<li class="empty">Station data could not load. Use the reload button above to try again.</li>';$('detail').hidden=true}else notify('Could not reload observations. Your current view is preserved.')}finally{$('reload').disabled=false}}
function openHelp(){ $('help').hidden=false;$('help-toggle').setAttribute('aria-expanded','true');$('help-close').focus() }
function closeHelp(){ $('help').hidden=true;$('help-toggle').setAttribute('aria-expanded','false');$('help-toggle').focus() }
$('help-toggle').addEventListener('click',()=>{$('help').hidden?openHelp():closeHelp()});$('help-close').addEventListener('click',closeHelp);$('method-link').addEventListener('click',openHelp);$('update-help').addEventListener('click',()=>{openHelp();$('update-instructions').open=true;$('update-instructions').scrollIntoView({block:'nearest'})});document.addEventListener('keydown',ev=>{if(ev.key==='Escape'){if(!$('help').hidden)closeHelp();setChoosing(false)}});
$('search').addEventListener('input',renderList);$('sort').addEventListener('change',()=>{renderList();if($('sort').value==='distance'&&!origin)notify('Choose a starting point to sort by distance.')});$('fuel').addEventListener('change',()=>{renderList();renderDetail()});$('show-all').addEventListener('click',fitAll);
$('reload').addEventListener('click',()=>loadData(!dataset));$('retry-map').addEventListener('click',()=>{if(!map){initMap()}else{mapReady=false;$('map-error').hidden=true;map.setStyle('https://tiles.openfreemap.org/styles/positron');map.once('idle',()=>{mapReady=true;$('map-error').hidden=true});setTimeout(()=>{if(!mapReady)$('map-error').hidden=false},12000)}});
$('choose-point').addEventListener('click',()=>{if(!map){notify('The map needs to load before choosing a point.');return}setChoosing(!choosing);if(choosing&&matchMedia('(max-width:760px)').matches)$('map').scrollIntoView({behavior:'smooth',block:'center'})});
$('clear-origin').addEventListener('click',()=>{origin=null;writeStorage(ORIGIN,null);setChoosing(false);updateOrigin()});
$('locate').addEventListener('click',()=>{if(!navigator.geolocation){notify('Location is unavailable. Choose a point on the map.');return}$('locate').disabled=true;$('origin-status').textContent='Finding your location…';navigator.geolocation.getCurrentPosition(pos=>{origin=[pos.coords.longitude,pos.coords.latitude];writeStorage(ORIGIN,origin);setChoosing(false);updateOrigin();$('locate').disabled=false;fitAll()},()=>{$('locate').disabled=false;updateOrigin();$('origin-status').textContent='Location unavailable. You can choose a point on the map.'},{enableHighAccuracy:false,timeout:12000,maximumAge:60000})});
$('reset-checks').addEventListener('click',()=>{checks={};writeStorage(STORE,checks);if(dataset){applyChecks();renderList();renderDetail()}$('reset-status').textContent='Your saved checks were cleared. Original observations restored.'});
window.addEventListener('hashchange',()=>{const id=location.hash.slice(1);if(stations.some(s=>s.id===id))selectStation(id,true)});
setInterval(()=>{if(!dataset)return;$('snapshot-title').textContent=snapshotLabel();renderList();const s=stations.find(x=>x.id===selected),label=$('detail').querySelector('.checked');if(s?.checkedAt&&label)label.innerHTML=`${s.personal?'Your check':'Google Maps observation'} · ${dateLabel(s.checkedAt)}${isOld(s.checkedAt)?'<br><strong>Older observation — check live traffic.</strong>':''}`},60000);
loadData(true);
